import { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import { AnimationControls, useAnimation } from "framer-motion";

/**
 * Used to scroll an element vertically when it is not in view. Stops when its in view
 *
 * Usage:
 * ```tsx
 *
 * const [controls, refCallback] = useVerticalScroll(20)
 * ...
 *
 * return (
 * <div>
 *  <motion.div animate={controls}>
 *    <h1 ref={refCallback}>Heading</h1> //We will scroll to this element
 *  </motion.div>
 * </div>
 * )
 *
 * ```
 * @param scrollSpeed The amount of pixels per second that the scroll speed will have
 * @param rootElement The root element that the observer should use. If not provided, the viewport will be used
 * @returns A tuple with the controls to animate the scroll and a ref callback to attach to the element that should be scrolled to
 */
export const useVerticalScroll = (
  scrollSpeed: number,
  rootElement?: React.RefObject<Element>,
): [AnimationControls, (node: Element | null) => void] => {
  // We set the distance to scroll to a very large negative number to make sure we will eventually reach the element.
  // The scroll duration is calculated based on the scroll speed in order to guarantee a smooth scroll.
  const SCROLL_DISTANCE_PIXELS = Number.MIN_SAFE_INTEGER;
  const scrollDurationSeconds = SCROLL_DISTANCE_PIXELS / scrollSpeed;

  const controls = useAnimation();
  const [elementIsInView, setElementIsInView] = useState(true);
  const observerRef = useRef<IntersectionObserver | null>(null);

  const observeOrUnobserveElement = useCallback(
    (element: Element | null) => {
      if (observerRef.current) {
        observerRef.current.disconnect();
      }

      observerRef.current = new IntersectionObserver(
        ([entry]) => {
          setElementIsInView(entry.isIntersecting);
        },
        {
          root: rootElement?.current ?? null,
          threshold: 1,
        },
      );

      if (element) {
        observerRef.current.observe(element);
      }

      if (!element && observerRef.current) {
        controls.stop();
        observerRef.current.disconnect();
      }
    },
    [rootElement, controls],
  );

  const refCallback = useCallback(
    (node: Element | null) => {
      observeOrUnobserveElement(node);
    },
    [observeOrUnobserveElement],
  );

  useEffect(() => {
    if (!elementIsInView) {
      const handleScroll = async () => {
        await controls.start({
          y: [0, SCROLL_DISTANCE_PIXELS],
          transition: { duration: Math.abs(scrollDurationSeconds), ease: "linear" },
        });
      };

      handleScroll();
    }
  }, [elementIsInView, controls, SCROLL_DISTANCE_PIXELS, scrollDurationSeconds]);

  useLayoutEffect(() => {
    if (elementIsInView) {
      controls.stop();
    }
  }, [elementIsInView, controls]);

  return [controls, refCallback];
};
